body.script:
(function () {
  var DATA = [
    { e: "⚡", n: "KITE", l: ["https://f5fy.z13.web.core.windows.net","https://ofiq.z19.web.core.windows.net","https://qb3p.z9.web.core.windows.net","https://tq7o.z4.web.core.windows.net"] },
    { e: "☀️", n: "SOLARA", l: ["https://solara.tokeslaszlo.ro","https://solara.survet.cl","https://solara.explosionlearning.org","https://solara.lasersoft.net.au","https://solara.actadigital.com.ar","https://solara.aurorainsights.xyz"] },
    { e: "🌙", n: "LUNAR", l: ["https://lunar.explosionlearning.org","https://lunar.actadigital.com.ar","https://saugatrlunar-uicvr.xcel.ch"] },
    { e: "🌌", n: "AURORA", l: ["https://aurora.tokeslaszlo.ro","https://aurora.explosionlearning.org","https://aurora.actadigital.com.ar"] },
    { e: "✨", n: "GLIM", l: ["https://sgt7.s3.amazonaws.com/index.html","https://s3.us-east-1.amazonaws.com/axk4/index.html","https://s3.amazonaws.com/sz1n/index.html","https://axk4.s3.amazonaws.com/index.html"] },
    { e: "💭", n: "DAYDREAMX", l: ["https://h7ww.s3.amazonaws.com/index.html","https://h7ww.s3.us-east-1.amazonaws.com/index.html","https://s3.amazonaws.com/h7ww/index.html"] },
    { e: "🚀", n: "INTERSTELLAR", l: ["https://gnd9.z13.web.core.windows.net","https://zzqf.z19.web.core.windows.net","https://agek.z5.web.core.windows.net","https://fyeq.z1.web.core.windows.net","https://p4x5.z11.web.core.windows.net"] },
    { e: "🎭", n: "CINERA", l: ["https://cinera.explosionlearning.org","https://cinera.actadigital.com.ar"] },
    { e: "🔥", n: "FLARE", l: ["https://note.adis.web.id","https://max.brusin.net","https://lab.labgarreguevara.com.ar","https://study.innovacioneseducativas.com.mx","https://global.mrgshri.in"] },
    { e: "🌆", n: "UTOPIA", l: ["https://utopia.tokeslaszlo.ro","https://utopia.explosionlearning.org","https://utopia.actadigital.com.ar"] },
    { e: "🎬", n: "TRIPLE T HD", l: ["https://triplethd.explosionlearning.org","https://triplethd.lasersoft.net.au","https://triplethd.actadigital.com.ar"] },
    { e: "🛠️", n: "SPACE", l: ["https://space.explosionlearning.org","https://space.actadigital.com.ar"] },
    { e: "🧺", n: "VOYA", l: ["https://voya.tokeslaszlo.ro","https://voya.explosionlearning.org","https://voya.actadigital.com.ar"] },
    { e: "🧳", n: "STROBERRI", l: ["https://stroberri.explosionlearning.org","https://stroberri.actadigital.com.ar"] },
    { e: "📚", n: "STUDY HUB", l: ["https://studyhub.tokeslaszlo.ro","https://studyhub.explosionlearning.org"] },
    { e: "🐤", n: "TUNG TUNG", l: ["https://tungtung.survet.cl","https://tungtung.nikeinvest.ro","https://tungtung.cpmecatronica.cl","https://tungtung.colegiosanmarcel.cl","https://jhkf.z21.web.core.windows.net"] },
    { e: "🏹", n: "ASTRA", l: ["https://sixseven.chanka.com","https://astra-bull.noble-house.tk","https://astra-education.top","https://animals.solidaritysafaris.com","https://bull.solidaritysafaris.com"] },
    { e: "🌴", n: "FERN", l: ["https://family267740-saugatr.biec.com.np","https://saugatrfern-pzamu.biec.com.np","https://education265213-saugatr.codex-bot.com","https://saugatrgreat.hyperion-edu.net"] },
    { e: "🧸", n: "DUCK SET", l: ["https://unpkg.com/classroomduck@1.0.0/index.html","https://unpkg.com/classroomduck@1.0.0/index.svg","https://esm.sh/classroomduck@1.0.0/index.html","https://cdn.jsdelivr.net/npm/classroomduck@1.0.0/index.html"] },
    { e: "📦", n: "S3 / AMAZON", l: ["https://leahh-5a8u.s3.amazonaws.com/index.html","https://lmeyo-cok1.s3.amazonaws.com/index.html","https://ralsei.s3.amazonaws.com/index.html","https://ralsei.s3.us-east-1.amazonaws.com/index.html"] },
    { e: "🎨", n: "EXTRAS", l: ["https://gelaoshi.global.ssl.fastly.net","https://fstudentsareinventors.s3.amazonaws.com/index.html","https://glwithfinals.s3.amazonaws.com/index.html","https://demo.example.com/extra/index.html"] },
    { e: "🌐", n: "MISC HOSTS", l: ["https://mathtechmrk61.parcomunica.com","https://edumathschooledu.parcomunica.com","https://rkmathtech3.parcomunica.com","https://itsforubaks.parcomunica.com"] },
    { e: "🧪", n: "B-CDN TEST SET", l: ["https://james-gonzalez-21.b-cdn.net","https://daniel-sanchez-82.b-cdn.net","https://jacob-thomas-19.b-cdn.net","https://lucas-jones-14.b-cdn.net","https://ethan-taylor-07.b-cdn.net"] },
    { e: "🔗", n: "JSDELIVR SVG DUMP", l: ["https://cdn.jsdelivr.net/gh/hameslabybu-web/svg@6fd2c561e28a4b6ca92ceb469dfdd36f863b71fe/index.svg","https://cdn.jsdelivr.net/gh/hameslabybu-web/svg@7d1af53c69234f7de4f5f8d3cc3c19ea4de10d17/index.svg"] },
    { e: "🧩", n: "GOOGLE SCRIPT + P5JS", l: ["https://script.google.com/macros/s/AKfycbxnbwF6Gs2_XnVzz_mBOInAp54aR2a7LLGyHn2AvEp-k765vSdQl5YnDfW6QT6zVU68/exec","https://script.google.com/macros/s/AKfycbxkQK0dTqD4M3T8lYdD107ZkA6H5YFQ8iwK2TtNPQq2u0qgWw/exec"] }
  ];

  var NOTES = "<h2>What Is Science?</h2>"
    + "<p>Science is the systematic study of the natural world through observation, experimentation, and reasoning. Scientists ask questions, form hypotheses, collect data, and draw conclusions based on evidence.</p>"
    + "<p>The three main branches of science:</p>"
    + "<ul><li><strong>Life Science</strong> — the study of living things (biology)</li><li><strong>Physical Science</strong> — the study of matter and energy (chemistry + physics)</li><li><strong>Earth and Space Science</strong> — the study of Earth, planets, and the universe</li></ul>"
    + "<h2>The Scientific Method</h2>"
    + "<p>The scientific method is a step-by-step process scientists use to investigate questions. The steps are not always linear — scientists often loop back and revise.</p>"
    + "<ol><li><strong>Ask a Question</strong> — What do you want to know?</li><li><strong>Research</strong> — What do you already know? What have others discovered?</li><li><strong>Form a Hypothesis</strong> — Make a testable prediction.</li><li><strong>Test It</strong> — Design and run an experiment.</li><li><strong>Analyze Data</strong> — Look for patterns and results.</li><li><strong>Draw Conclusions</strong> — Explain what your evidence shows.</li></ol>"
    + "<h2>Variables and Controls</h2>"
    + "<p>Every good experiment has three types of variables:</p>"
    + "<ul><li><strong>Independent Variable (IV)</strong> — The one thing you change on purpose.</li><li><strong>Dependent Variable (DV)</strong> — The thing you measure; it depends on the IV.</li><li><strong>Constants</strong> — Things you keep the same so the test is fair.</li></ul>"
    + "<p><strong>Control Group:</strong> The group that does not receive the experimental treatment. Used for comparison. Example: A plant given no fertilizer while others get fertilizer.</p>"
    + "<p><strong>Experimental Group:</strong> The group that receives the treatment.</p>"
    + "<h2>Data and Graphing</h2>"
    + "<p>Data comes in two flavors:</p>"
    + "<ul><li><strong>Qualitative Data</strong> — Descriptions. Uses your senses. (\"The liquid turned cloudy.\")</li><li><strong>Quantitative Data</strong> — Numbers. Measurements. (\"The water was 24°C.\")</li></ul>"
    + "<p>Types of graphs:</p>"
    + "<ul><li><strong>Bar Graph</strong> — Comparing categories.</li><li><strong>Line Graph</strong> — Showing change over time.</li><li><strong>Pie Chart</strong> — Showing parts of a whole.</li></ul>"
    + "<p>Rules for graphing: label both axes with units, give the graph a title like <code>The Effect of [IV] on [DV]</code>, and use neat, accurate scales. Neatness counts.</p>"
    + "<h2>Example — Why Bread Gets Soggy</h2>"
    + "<bq><strong>Question:</strong> Why does my sandwich bread get soggy when I put sauce on it?<br/><br/><strong>Background research:</strong> Bread is porous — it has tiny holes. Sauce contains water, which can move into the bread and make it soft.<br/><br/><strong>Hypothesis:</strong> More sauce will make the bread soggier because the water content increases.</bq>"
    + "<h2>Vocabulary Review</h2>"
    + "<table><tr><th>Term</th><th>Definition</th></tr><tr><td>Science</td><td>The systematic study of the natural world</td></tr><tr><td>Hypothesis</td><td>A testable prediction based on observations</td></tr><tr><td>Independent Variable</td><td>The variable the scientist changes on purpose</td></tr><tr><td>Dependent Variable</td><td>The variable that is measured</td></tr><tr><td>Control Group</td><td>The group that receives no experimental treatment</td></tr><tr><td>Constant</td><td>A factor that stays the same in an experiment</td></tr><tr><td>Data</td><td>Information collected during an experiment</td></tr><tr><td>Qualitative Data</td><td>Descriptive observations using the senses</td></tr><tr><td>Quantitative Data</td><td>Numerical measurements</td></tr><tr><td>Inference</td><td>A logical conclusion based on evidence</td></tr><tr><td>Observation</td><td>Information gathered using the five senses</td></tr><tr><td>Theory</td><td>A well-tested explanation supported by much evidence</td></tr><tr><td>Law</td><td>A rule describing a pattern in nature</td></tr><tr><td>Model</td><td>A representation used to explain something</td></tr></table>"
    + "<p style='margin-top:26px;font-style:italic;color:var(--mut);font-size:13px'>End of Chapter 1 notes. Additional reference material available via the button in the corner.</p>";

  var root = document.getElementById("app-root");
  var style = document.createElement("style");
  style.textContent = "";
  document.head.appendChild(style);
  var html = ""
    + "<div class='wrap'>"
    + "  <header class='head'>"
    + "    <div class='brand'>"
    + "      <div class='hi'>🧪</div>"
    + "      <div class='ht'>"
    + "        <h1>Science Packet — Chapter 1 Review</h1>"
    + "        <div class='meta'><span>3rd Period</span><span>Room 221</span><span>Mrs. C</span></div>"
    + "      </div>"
    + "    </div>"
    + "    <div class='actions'>"
    + "      <button type='button' class='tab on' id='notesTab'>Notes</button>"
    + "      <button type='button' class='tab' id='vaultTab'>Vault</button>"
    + "      <button type='button' class='theme' id='themeBtn' aria-label='Toggle theme'>🌙</button>"
    + "    </div>"
    + "  </header>"
    + "  <main>"
    + "    <section class='pn on' id='panelNotes'><div class='nt'>" + NOTES + "</div></section>"
    + "    <section class='pn' id='panelVault'>"
    + "      <div class='srch'><span class='srch-icon'>⌕</span><input id='searchInput' type='text' placeholder='Search groups or links…' autocomplete='off' spellcheck='false'/><span class='srch-key'>/</span></div>"
    + "      <div id='grid' class='gr'></div>"
    + "      <div id='noResults' class='nr'>No matching links found.</div>"
    + "    </section>"
    + "  </main>"
    + "</div>"
    + "<div class='to' id='toast'>copied</div>"
    + "<div class='sb' id='secretBtn' title='Open vault'>✦</div>";

  root.innerHTML = html;

  var grid = document.getElementById("grid");
  var noResults = document.getElementById("noResults");
  var searchInput = document.getElementById("searchInput");
  var toast = document.getElementById("toast");
  var panelNotes = document.getElementById("panelNotes");
  var panelVault = document.getElementById("panelVault");
  var secretBtn = document.getElementById("secretBtn");
  var themeBtn = document.getElementById("themeBtn");
  var notesTab = document.getElementById("notesTab");
  var vaultTab = document.getElementById("vaultTab");
  var vaultOpen = false;

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return {"&":"&amp;","<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;"}[c];
    });
  }

  function showToast(message) {
    toast.textContent = message;
    toast.classList.add("on");
    clearTimeout(showToast._t);
    showToast._t = setTimeout(function () { toast.classList.remove("on"); }, 1600);
  }

  function fallbackCopy(url, btn) {
    var ta = document.createElement("textarea");
    ta.value = url;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand("copy");
      showToast("copied");
    } catch (e) {}
    document.body.removeChild(ta);
    if (btn) {
      btn.classList.add("ok");
      btn.textContent = "✓";
      setTimeout(function () {
        btn.classList.remove("ok");
        btn.textContent = "📋";
      }, 1200);
    }
  }

  function render() {
    if (!grid) return;
    grid.innerHTML = "";
    DATA.forEach(function (g) {
      var card = document.createElement("div");
      card.className = "gp";
      card.dataset.n = g.n.toLowerCase();
      card.dataset.l = g.l.join(" ").toLowerCase();

      var content = "<div class='gh'><div class='ge'>" + g.e + "</div><div class='gn'>" + esc(g.n) + "</div><div class='gc'>" + g.l.length + "</div><div class='gv'>▾</div></div><div class='gb'>";

      g.l.forEach(function (u) {
        content += "<div class='link-row'><a class='lk' href='" + esc(u) + "' target='_blank' rel='noopener noreferrer' data-u='" + esc(u) + "'><span class='lt'>" + esc(u.replace(/^https?:\/\//, "")) + "</span></a><button class='lc' type='button' title='Copy link'>📋</button></div>";
      });

      content += "</div>";
      card.innerHTML = content;

      var head = card.querySelector(".gh");
      head.onclick = function (e) {
        if (e.target && e.target.closest && e.target.closest(".lc")) return;
        card.classList.toggle("col");
      };

      var copyButtons = card.querySelectorAll(".lc");
      for (var i = 0; i < copyButtons.length; i++) {
        (function (btn) {
          btn.onclick = function (e) {
            e.preventDefault();
            e.stopPropagation();
            var url = btn.parentNode.querySelector(".lk").dataset.u;
            try {
              if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(url).then(function () {
                  btn.classList.add("ok");
                  btn.textContent = "✓";
                  showToast("copied");
                  setTimeout(function () {
                    btn.classList.remove("ok");
                    btn.textContent = "📋";
                  }, 1200);
                }).catch(function () { fallbackCopy(url, btn); });
              } else {
                fallbackCopy(url, btn);
              }
            } catch (err) {
              fallbackCopy(url, btn);
            }
          };
        })(copyButtons[i]);
      }

      grid.appendChild(card);
    });
  }

  function filter(query) {
    query = (query || "").trim().toLowerCase();
    var visible = false;
    var cards = document.querySelectorAll(".gp");
    for (var i = 0; i < cards.length; i++) {
      var c = cards[i];
      var match = !query || c.dataset.n.indexOf(query) !== -1 || c.dataset.l.indexOf(query) !== -1;
      c.style.display = match ? "" : "none";
      if (match) visible = true;
    }
    if (noResults) {
      noResults.classList.toggle("on", !visible);
    }
  }

  function setPanel(open) {
    vaultOpen = open;
    if (open) {
      panelNotes.classList.remove("on");
      panelVault.classList.add("on");
      notesTab.classList.remove("on");
      vaultTab.classList.add("on");
      if (secretBtn) secretBtn.classList.add("on");
      render();
      if (searchInput) {
        searchInput.value = "";
        filter("");
      }
    } else {
      panelVault.classList.remove("on");
      panelNotes.classList.add("on");
      vaultTab.classList.remove("on");
      notesTab.classList.add("on");
      if (secretBtn) secretBtn.classList.remove("on");
    }
    window.scrollTo(0, 0);
  }

  function secretClick(e) {
    if (e) e.stopPropagation();
    setPanel(!vaultOpen);
  }

  if (secretBtn) {
    secretBtn.addEventListener("click", secretClick, false);
    secretBtn.addEventListener("touchstart", secretClick, { passive: true });
  }

  if (notesTab) {
    notesTab.addEventListener("click", function () { setPanel(false); });
  }
  if (vaultTab) {
    vaultTab.addEventListener("click", function () { setPanel(true); });
  }

  if (searchInput) {
    searchInput.addEventListener("input", function (e) {
      filter(e.target.value);
    });
  }

  document.addEventListener("keydown", function (e) {
    if (e.key === "/" && document.activeElement !== searchInput && searchInput) {
      e.preventDefault();
      searchInput.focus();
      searchInput.select();
    }
    if (e.key === "Escape") {
      if (vaultOpen) {
        setPanel(false);
      }
    }
  });

  var savedTheme = "dark";
  try {
    savedTheme = localStorage.getItem("theme") || "dark";
  } catch (e) {}
  document.documentElement.setAttribute("data-th", savedTheme);
  if (themeBtn) {
    themeBtn.textContent = savedTheme === "dark" ? "🌙" : "☀️";
    function toggleTheme(e) {
      if (e) e.stopPropagation();
      var current = document.documentElement.getAttribute("data-th");
      var next = current === "dark" ? "light" : "dark";
      document.documentElement.setAttribute("data-th", next);
      try { localStorage.setItem("theme", next); } catch (err) {}
      themeBtn.textContent = next === "dark" ? "🌙" : "☀️";
    }
    themeBtn.addEventListener("click", toggleTheme, false);
    themeBtn.addEventListener("touchstart", toggleTheme, { passive: true });
    themeBtn.onclick = toggleTheme;
  }

  render();
})();
